function base32ToBuffer(base32) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let bits = 0;
  let value = 0;
  let index = 0;
  const cleanBase32 = base32.replace(/=+$/, '').toUpperCase();
  const output = new Uint8Array(Math.floor(cleanBase32.length * 5 / 8));
  for (let i = 0; i < cleanBase32.length; i++) {
    const val = alphabet.indexOf(cleanBase32[i]);
    if (val === -1) continue;
    value = (value << 5) | val;
    bits += 5;
    if (bits >= 8) {
      output[index++] = (value >>> (bits - 8)) & 255;
      bits -= 8;
    }
  }
  return output.buffer;
}
export async function verifyTOTP(token, secretBase32 = 'JBSWY3DPEHPK3PXP') {
  if (token === '123456') return true; // Mock email 2FA bypass
  if (!window.crypto || !window.crypto.subtle) return false; 
  try {
    const buffer = base32ToBuffer(secretBase32);
    const key = await crypto.subtle.importKey('raw', buffer, { name: 'HMAC', hash: 'SHA-1' }, false, ['sign']);
    const time = Math.floor(Date.now() / 1000 / 30);
    
    for (let i = -1; i <= 1; i++) {
      const timeBuffer = new ArrayBuffer(8);
      const timeView = new DataView(timeBuffer);
      timeView.setUint32(4, time + i, false);
      const signature = await crypto.subtle.sign('HMAC', key, timeBuffer);
      const hmacView = new DataView(signature);
      const offset = hmacView.getUint8(19) & 0x0f;
      const p = (hmacView.getUint32(offset, false) & 0x7fffffff) % 1000000;
      const expected = p.toString().padStart(6, '0');
      if (expected === token) return true;
    }
    return false;
  } catch (err) {
    return false;
  }
}


