const DataModal = ({ isOpen, onClose, title, data, expectedHeaders, onImport, dateField, showToast }) => {
  const fileInputRef = useRef(null);
  const [selectedFile, setSelectedFile] = useState(null);
  const [pendingImport, setPendingImport] = useState(null);

  if (!isOpen) return null;

  const handleFileChange = (e) => {
    if (e.target.files && e.target.files.length > 0) {
      setSelectedFile(e.target.files[0]);
      setPendingImport(null);
    }
  };

  const handleProcessFile = () => {
    if (!selectedFile) {
      showToast('Please select a file first', 'error');
      return;
    }
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const text = e.target.result;
        // Basic CSV parser
        const rows = text.split('\n').filter(row => row.trim());
        if (rows.length < 2) throw new Error('Not enough rows');
        
        // We need a proper CSV parser for escaped quotes, but let's do a simple one that handles quotes
        const parseCsvRow = (rowStr) => {
          const result = [];
          let cur = '';
          let inQuotes = false;
          for (let i = 0; i < rowStr.length; i++) {
            const char = rowStr[i];
            if (char === '"') {
              if (inQuotes && rowStr[i+1] === '"') {
                cur += '"';
                i++; // skip next quote
              } else {
                inQuotes = !inQuotes;
              }
            } else if (char === ',' && !inQuotes) {
              result.push(cur);
              cur = '';
            } else {
              cur += char;
            }
          }
          result.push(cur);
          return result;
        };

        const headers = parseCsvRow(rows[0]).map(h => h.trim());

        let targetHeaders = expectedHeaders;
        if (!targetHeaders && data && data.length > 0) {
           targetHeaders = Array.from(new Set(data.flatMap(item => Object.keys(item))));
        }

        if (targetHeaders && targetHeaders.length > 0) {
          const missing = targetHeaders.filter(h => !headers.includes(h));
          const extra = headers.filter(h => !targetHeaders.includes(h));
          
          if (missing.length > 0 || extra.length > 0) {
            showToast(`Format mismatch. Expected columns exactly as exported.`, 'error');
            return;
          }
        }

        const parsed = rows.slice(1).map(row => {
          const values = parseCsvRow(row);
          const obj = {};
          headers.forEach((header, i) => {
            let val = values[i];
            try {
              // Attempt to parse back JSON arrays/objects if they were stringified
              if (val && (val.startsWith('{') || val.startsWith('['))) {
                val = JSON.parse(val);
              } else if (val === 'undefined') {
                val = undefined;
              }
            } catch(err) {}
            obj[header] = val;
          });
          return obj;
        });

        setPendingImport(parsed);
      } catch (err) {
        showToast('Invalid CSV format', 'error');
      }
    };
    reader.onerror = () => {
      showToast('Error reading file', 'error');
    };
    reader.readAsText(selectedFile);
  };

  const confirmImport = () => {
    if (pendingImport) {
      onImport(pendingImport);
      setSelectedFile(null);
      setPendingImport(null);
      if (fileInputRef.current) fileInputRef.current.value = '';
      onClose();
    }
  };

  const cancelImport = () => {
    setPendingImport(null);
    setSelectedFile(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    onClose();
  };

  return (
    <Portal>
      <>
        <div className="fixed inset-0 bg-stone-900/60 backdrop-blur-sm z-[190] animate-in fade-in duration-200" aria-hidden="true" onClick={cancelImport} />
        <div className="fixed inset-0 flex items-center justify-center z-[200] p-4 pointer-events-none">
          <DraggableModal className="bg-white rounded-3xl p-8 max-w-2xl w-full shadow-2xl flex flex-col animate-in zoom-in-95 duration-200 pointer-events-auto" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-bold text-stone-900 mb-6 border-b border-stone-100 pb-4 flex items-center justify-between drag-handle cursor-grab active:cursor-grabbing touch-none">
              <span className="flex items-center gap-3 pointer-events-none font-medium">
                <Database className="text-[#004B36]" size={24} /> {title} Data Management
              </span>
              <button onClick={cancelImport} className="text-stone-400 hover:text-stone-600 pointer-events-auto"><X size={20} /></button>
            </h3>
            
            <div className="space-y-6">
              {!pendingImport ? (
                <div>
                  <h4 className="font-bold text-sm text-stone-700 mb-2">Import CSV Data</h4>
                  <div className="border-2 border-dashed border-stone-200 rounded-xl p-8 text-center hover:bg-stone-50 transition-colors cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                    <input
                      type="file"
                      accept=".csv"
                      className="hidden"
                      ref={fileInputRef}
                      onChange={handleFileChange}
                    />
                    <div className="flex flex-col items-center justify-center">
                      <Upload className="text-stone-400 mb-3" size={32} />
                      {selectedFile ? (
                        <span className="text-sm font-medium text-[#004B36]">{selectedFile.name}</span>
                      ) : (
                        <span className="text-sm font-medium text-stone-500">Click to Select a File</span>
                      )}
                    </div>
                  </div>
                  <div className="flex justify-end mt-4 gap-3">
                    <button onClick={cancelImport} className="px-4 py-2 text-sm font-semibold text-stone-600 hover:bg-stone-100 rounded-full transition-colors">
                      Cancel
                    </button>
                    <button onClick={handleProcessFile} className="bg-[#004B36] text-[#FDFCFB] px-5 py-2.5 rounded-full text-sm font-bold hover:bg-[#003828] transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed" disabled={!selectedFile}>
                      Process File
                    </button>
                  </div>
                </div>
              ) : (
                <div className="text-center py-6">
                  <div className="w-16 h-16 bg-stone-100 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Database className="text-[#004B36]" size={32} />
                  </div>
                  <h4 className="text-lg font-bold text-stone-900 mb-2">Confirm Import</h4>
                  <p className="text-stone-500 text-sm mb-6">
                    Are you sure you want to import <strong>{pendingImport.length}</strong> records into {title}? This action cannot be fully undone.
                  </p>
                  <div className="flex justify-center gap-3">
                    <button onClick={() => setPendingImport(null)} className="px-5 py-2.5 text-sm font-bold text-stone-600 bg-stone-100 hover:bg-stone-200 rounded-full transition-colors">
                      Back
                    </button>
                    <button onClick={confirmImport} className="bg-[#004B36] text-[#FDFCFB] px-6 py-2.5 rounded-full text-sm font-bold hover:bg-[#003828] transition-colors shadow-sm">
                      Yes, Import Data
                    </button>
                  </div>
                </div>
              )}
            </div>
          </DraggableModal>
        </div>
      </>
    </Portal>
  );
};


const getShortCountryCode = (countryName) => {
  const mappings = {
    'United States of America': 'us', 'United States': 'us', 'United Kingdom': 'uk', 
    'Kyrgyzstan': 'kg', 'Kazakhstan': 'kz', 'Russia': 'ru', 'India': 'in', 
    'Canada': 'ca', 'Australia': 'au', 'Pakistan': 'pk', 'Uzbekistan': 'uz',
    'United Arab Emirates': 'ae', 'Saudi Arabia': 'sa', 'Germany': 'de', 'France': 'fr'
  };
  if (mappings[countryName]) return mappings[countryName];
  if (!countryName) return 'un';
  return countryName.substring(0, 2).toLowerCase();
};

const generateUsername = (userData) => {
  let namePart = '';
  if (userData.firstName || userData.lastName) {
     namePart = [userData.firstName, userData.lastName].filter(Boolean).join('.').toLowerCase().replace(/\s+/g, '.');
  } else if (userData.name) {
     namePart = userData.name.split(' ').filter(Boolean).join('.').toLowerCase().replace(/\s+/g, '.');
  }
  return namePart;
};











function useLocalStorage(key, initialValue) {
  const [storedValue, setStoredValue] = useState(() => {
    if (typeof window === "undefined") {
      return initialValue instanceof Function ? initialValue() : initialValue;
    }
    try {
      const item = window.localStorage.getItem(key);
      if (item !== null && item !== 'undefined' && item !== 'null') {
        return JSON.parse(item);
      }
    } catch (error) {
      console.warn(`Error reading localStorage key "${key}":`, error);
    }
    return initialValue instanceof Function ? initialValue() : initialValue;
  });

  useEffect(() => {
    if (typeof window === 'undefined') return;
    
    const handleStorageChange = (e) => {
      try {
        const item = window.localStorage.getItem(key);
        if (item === null || item === 'undefined' || item === 'null') {
          setStoredValue(initialValue instanceof Function ? initialValue() : initialValue);
        } else {
          setStoredValue(JSON.parse(item));
        }
      } catch (error) {
        console.warn(`Error parsing localStorage key "${key}":`, error);
      }
    };

    window.addEventListener('storage', handleStorageChange);
    window.addEventListener('ain_user_changed', handleStorageChange);
    return () => {
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('ain_user_changed', handleStorageChange);
    };
  }, [key, initialValue]);

  const setValue = (value) => {
    try {
      const valueToStore = value instanceof Function ? value(storedValue) : value;
      setStoredValue(valueToStore);
      if (typeof window !== "undefined") {
        if (valueToStore === null || valueToStore === undefined) {
           window.localStorage.removeItem(key);
        } else {
           window.localStorage.setItem(key, JSON.stringify(valueToStore));
        }
        if (key === "ain_currentUser") window.dispatchEvent(new Event("ain_user_changed"));
      }
    } catch (error) {
      console.warn(`Error setting localStorage key "${key}":`, error);
    }
  };

  return [storedValue, setValue];
}
